from typing import List
import math

def findKthSmallest(coins: List[int], k: int) -> int:
    l = 0
    r = 10**18
    n = len(coins)

    while l + 1 < r:
        m = (l + r) >> 1

        def check(x):
            count = 0
            lcm = 0
            c = []
            for mask in range(1 << n):
                cnt = 0
                for i in range(n):
                    if (mask >> i) & 1:
                        cnt += 1
                        c.append(coins[i])
                if cnt > 0:
                    lcm = math.lcm(*c)
                    count += x // lcm
                    if cnt % 2 == 0:
                        count -= x // lcm
                c.clear()
            return count >= k

        result = check(m)
        if result:
            r = m
        else:
            l = m

    return r
